// Device wallet: the testnet fallback for players with no wallet. A plain key
// generated in this browser and kept in localStorage, exposed as an EIP-1193
// provider so the normal BrowserProvider/sendTx path signs with it unchanged.
//
// Why not a hosted wallet: Coinbase Smart Wallet connects on Ethereum Sepolia
// but refuses to sign there ("Sepolia is not supported", phone review
// 2026-10-18), and every app-based wallet needs a hand-off that Android Chrome
// breaks. Testnet ETH has no value, so a browser-held key is the right trade:
// no popup, no app, no third party, a buy is one tap plus the block.
// Never offered on mainnet (testnetOnly), where Coinbase Smart Wallet is used.

// The full ethers build: the app's slim 'ethers' bundle (db/build-ethers-vendor
// .mjs) leaves out Wallet, and only players who pick this wallet load it.
import { ethers } from '../vendor/ethers.mjs';
import { CHAIN } from './chain-config.js';
import { _makeFailoverSend } from './read-provider.js';

const STORE_PREFIX = 'degenerus:device-wallet:';
// Wallet methods answered here; everything else is a plain RPC read.
const LOCAL = new Set([
  'eth_requestAccounts', 'eth_accounts', 'eth_chainId', 'net_version',
  'wallet_switchEthereumChain', 'wallet_addEthereumChain',
  'eth_sendTransaction', 'personal_sign', 'eth_signTypedData_v4',
]);

export function deviceWalletSupported(chain = CHAIN) {
  return Number(chain?.id) !== 1;
}

function storeKey(chain = CHAIN) {
  return `${STORE_PREFIX}${Number(chain.id)}`;
}

/** True when this browser already holds a device wallet for the chain. */
export function hasDeviceWallet(chain = CHAIN) {
  try { return Boolean(globalThis.localStorage?.getItem(storeKey(chain))); }
  catch (_e) { return false; }
}

function rpcProvider(chain = CHAIN) {
  // Uncached on purpose: the shared read provider's cache could hand back a
  // stale pending nonce between two quick buys.
  const provider = new ethers.JsonRpcProvider(chain.rpcUrl, Number(chain.id), { staticNetwork: true });
  const fallbacks = Array.isArray(chain.fallbackRpcUrls) ? chain.fallbackRpcUrls.filter(Boolean) : [];
  if (fallbacks.length > 0) provider._send = _makeFailoverSend([chain.rpcUrl, ...fallbacks]);
  return provider;
}

function loadOrCreateWallet(chain = CHAIN, create = true) {
  const key = storeKey(chain);
  let secret = null;
  try { secret = globalThis.localStorage?.getItem(key) || null; } catch (_e) { /* private mode */ }
  if (!secret) {
    if (!create) return null;
    secret = ethers.Wallet.createRandom().privateKey;
    try { globalThis.localStorage?.setItem(key, secret); } catch (_e) { /* page-lifetime wallet */ }
  }
  return new ethers.Wallet(secret);
}

const big = (value) => (value == null ? undefined : BigInt(value));

/**
 * EIP-1193 provider over the device wallet. create=false only restores an
 * existing wallet (silent reconnect) and returns null when there is none.
 */
export function deviceWalletProvider({ chain = CHAIN, create = true } = {}) {
  if (!deviceWalletSupported(chain)) return null;
  const base = loadOrCreateWallet(chain, create);
  if (!base) return null;
  const rpc = rpcProvider(chain);
  const signer = base.connect(rpc);
  const address = signer.address.toLowerCase();
  const listeners = new Map();
  const hexChain = `0x${Number(chain.id).toString(16)}`;

  const request = async ({ method, params = [] } = {}) => {
    if (!LOCAL.has(method)) return rpc.send(method, params);
    switch (method) {
      case 'eth_requestAccounts':
      case 'eth_accounts':
        return [address];
      case 'eth_chainId':
        return hexChain;
      case 'net_version':
        return String(Number(chain.id));
      case 'wallet_switchEthereumChain':
      case 'wallet_addEthereumChain': {
        const wanted = String(params?.[0]?.chainId || '').toLowerCase();
        if (wanted && wanted !== hexChain) {
          throw Object.assign(new Error('This test wallet only runs on ' + (chain.name || 'this network')), { code: 4902 });
        }
        return null;
      }
      case 'eth_sendTransaction': {
        const tx = params[0] || {};
        const sent = await signer.sendTransaction({
          to: tx.to || undefined,
          data: tx.data || tx.input || undefined,
          value: big(tx.value),
          gasLimit: big(tx.gas ?? tx.gasLimit),
          maxFeePerGas: big(tx.maxFeePerGas),
          maxPriorityFeePerGas: big(tx.maxPriorityFeePerGas),
          gasPrice: tx.maxFeePerGas == null ? big(tx.gasPrice) : undefined,
          nonce: tx.nonce == null ? undefined : Number(tx.nonce),
        });
        return sent.hash;
      }
      case 'personal_sign': {
        const [message] = params;
        return signer.signMessage(ethers.isHexString(message) ? ethers.getBytes(message) : String(message));
      }
      case 'eth_signTypedData_v4': {
        const data = typeof params[1] === 'string' ? JSON.parse(params[1]) : params[1];
        const { EIP712Domain: _domain, ...types } = data.types || {};
        return signer.signTypedData(data.domain, types, data.message);
      }
      default:
        throw Object.assign(new Error(`Unsupported method ${method}`), { code: 4200 });
    }
  };

  return {
    isDeviceWallet: true,
    address,
    request,
    on(event, fn) { if (!listeners.has(event)) listeners.set(event, new Set()); listeners.get(event).add(fn); },
    removeListener(event, fn) { listeners.get(event)?.delete(fn); },
    // The key stays in this browser: disconnecting only forgets the session,
    // so the player's test funds are still there when they come back.
    disconnect() { for (const fn of listeners.get('disconnect') || []) fn(); },
  };
}
